const FORMS = [{"id": "blackiron", "tier": 1, "name": "黑铁关羽", "assets": {"attack_cg": {"src": "assets/blackiron-attack_cg.webp", "width": 1672, "height": 941, "label": "黑铁关羽-主动爆发CG-透明候选2"}, "avatar": {"src": "assets/blackiron-avatar.webp", "width": 1254, "height": 1254, "label": "黑铁关羽-头像-透明候选2"}, "card": {"src": "assets/blackiron-card.webp", "width": 1190, "height": 1786, "label": "01-黑铁-UI排版修复1190"}}}, {"id": "bronze", "tier": 2, "name": "青铜关羽", "assets": {"attack_cg": {"src": "assets/bronze-attack_cg.webp", "width": 1536, "height": 1024, "label": "bronze_cg"}, "avatar": {"src": "assets/bronze-avatar.webp", "width": 1254, "height": 1254, "label": "bronze_avatar"}, "biography": {"src": "assets/bronze-biography.webp", "width": 1536, "height": 1024, "label": "桃园结义-v11-神话源重绘候选"}, "card": {"src": "assets/bronze-card.webp", "width": 1190, "height": 1786, "label": "02-青铜-UI排版修复1190"}}}, {"id": "silver", "tier": 3, "name": "白银关羽", "assets": {"attack_cg": {"src": "assets/silver-attack_cg.webp", "width": 1536, "height": 1024, "label": "silver_cg"}, "avatar": {"src": "assets/silver-avatar.webp", "width": 1254, "height": 1254, "label": "silver_avatar"}, "biography": {"src": "assets/silver-biography.webp", "width": 1536, "height": 1024, "label": "温酒请战-v17-原图冻结-武器局部合成"}, "card": {"src": "assets/silver-card.webp", "width": 1190, "height": 1786, "label": "03-白银-UI排版修复1190"}}}, {"id": "gold", "tier": 4, "name": "黄金关羽", "assets": {"attack_cg": {"src": "assets/gold-attack_cg.webp", "width": 1536, "height": 1024, "label": "gold_cg"}, "avatar": {"src": "assets/gold-avatar.webp", "width": 1254, "height": 1254, "label": "gold_avatar"}, "biography": {"src": "assets/gold-biography.webp", "width": 1536, "height": 1024, "label": "千里护行-神话源重绘-直杆修复"}, "card": {"src": "assets/gold-card.webp", "width": 1190, "height": 1786, "label": "04-黄金-UI排版修复1190"}}}, {"id": "mecha5", "tier": 5, "name": "机甲关羽", "assets": {"avatar": {"src": "assets/mecha5-avatar.webp", "width": 1254, "height": 1254, "label": "五星机甲关羽-头像-透明"}, "card": {"src": "assets/mecha5-card.webp", "width": 1190, "height": 1786, "label": "guanyu-piloted-dragon-mecha-5star"}, "biography": {"src": "assets/mecha5-biography.webp", "width": 1536, "height": 1024, "label": "五星机甲关羽-传记-青龙启甲-古代工坊组装重绘"}, "attack_cg": {"src": "assets/mecha5-attack_cg.webp", "width": 1536, "height": 1024, "label": "五星机甲关羽-放招-腾跃斜劈-透明"}}, "story": "山城被围，工坊中的炉火彻夜未熄。百工以青铜为骨、精铁为筋，把绞盘与齿轮连成巨甲的关节。关羽沿木架走入尚未封合的胸舱，等待这副庞大的身躯与自己接通。\n\n铁链缓缓绷紧，龙首肩甲、双臂与胸甲从不同吊架降下。匠人扶正传动轴，逐一落销，腿甲敞开的骨架里响起铜齿咬合的声音。前景的青龙巨刃仍架在夹具上校准握距，侧旁的机械赤兔也尚在安装四肢与外甲。人、甲、刀、马，就在满城匠人的协力中渐渐成形。\n\n最后一枚锁销落下之前，关羽回望炉火旁忙碌的众人。待巨甲迈出工坊，他要将这些亲手铸出它的人，护在刀锋之后。", "move": "巨甲腾跃而起，屈膝拧身，双手分握长柄斜劈而下。青色刀光沿巨刃划出连贯弧线，胸舱中的驾驶者清楚可见。动作表现重装机体蓄势后猛然反击的力量。", "storyTitle": "青龙启甲"}, {"id": "heritage5", "tier": 5, "name": "传承关羽", "assets": {"avatar": {"src": "assets/heritage5-avatar.webp", "width": 1254, "height": 1254, "label": "传承关羽-头像-透明"}, "biography": {"src": "assets/heritage5-biography.webp", "width": 1536, "height": 1024, "label": "传承关羽-传记-一刀分沧海"}, "attack_cg": {"src": "assets/heritage5-attack_cg.webp", "width": 1536, "height": 1024, "label": "传承关羽-放招-水淹七军-腾空回斩-透明"}, "card": {"src": "assets/heritage5-card.webp", "width": 1190, "height": 1786}}, "story": "暴雨压城，洪流漫过山川，战船在浪峰间起伏。关羽踏入怒涛，双手沉握青龙偃月刀，将奔腾的传承之力压入刀锋。\n\n一刀落下，洪水从脚前裂向天际。巨浪向两侧拔起如城壁，水底的岩脊、淤沙与残木尽数显露。刀光尚未散去，水墙之巅的战船已小如芥子。关羽压刀收势，长髯迎风，独立于乍现的海底长廊；远处的城门，正落在这一刀所指的尽头。\n\n此篇借“水淹七军”的意象展开幻想。一刀分海、露出海底与传承神力均为游戏虚构。", "move": "关羽腾空拧身，双手分握长柄回旋横斩，一腿屈起、一腿伸展。刀锋带出连续的青碧水刃，金角青龙沿水势盘绕向前。身体、长刀与水龙共同形成旋转的进攻走势。", "storyTitle": "一刀分沧海", "newCard": true}, {"id": "divine5", "tier": 5, "name": "神关羽", "assets": {"avatar": {"src": "assets/divine5-avatar.webp", "width": 1254, "height": 1254, "label": "神关羽-头像-透明"}, "biography": {"src": "assets/divine5-biography.webp", "width": 1536, "height": 1024, "label": "神关羽-传记-千秋共仰"}, "attack_cg": {"src": "assets/divine5-attack_cg.webp", "width": 1536, "height": 1024, "label": "神关羽-放招-义薄云天-透明"}, "card": {"src": "assets/divine5-card.webp", "width": 1190, "height": 1786}}, "story": "殿宇几度新修，阶前的香火仍在升起。画卷将后世不同年代的庙宇叠入同一片云光：帝王与官员执礼而来，行旅、军民与老幼也停在阶前，向武圣致敬。人们记住他的勇武，也将危难之中守诺护人的愿望寄托在这尊神相身上。\n\n香烟穿过重重庙院，青袍金甲的关羽端坐殿中，赤面长髯仍保留着人们熟悉的模样。光从神相身后铺开，照见一代又一代走过庙门的人。无数次郑重的叩拜，构成了“神关羽”的由来。\n\n祭祀画面采用跨时代艺术蒙太奇，并非记载所有帝王都曾亲祭关羽，也不表示不同朝代的人真实同场。", "move": "关羽凌空屈膝旋身，双手高举于额顶结印，衣袍与红绸随转势扬开。金翠冠冕与头后圣轮聚起光辉，三面宽阔的青金护盾沿身前展开，连成护域，表现“义薄云天”的神圣护佑之势。", "storyTitle": "千秋共仰", "newCard": true}, {"id": "demon5", "tier": 5, "name": "魔关羽", "assets": {"avatar": {"src": "assets/demon5-avatar.webp", "width": 1254, "height": 1254, "label": "魔关羽-头像-透明"}, "card": {"src": "assets/demon5-card.webp", "width": 1190, "height": 1786, "label": "guanyu-infernal-06-5star"}, "biography": {"src": "assets/demon5-biography.webp", "width": 1536, "height": 1024, "label": "魔关羽-传记-麦城未醒"}, "attack_cg": {"src": "assets/demon5-attack_cg.webp", "width": 1536, "height": 1024, "label": "魔关羽-放招-透明"}}, "story": "残旗垂在冷雨里。关羽被敌兵按跪在泥水中，身后的行刑刀已然举起。他没有低头，只透过散乱的长髯望向天空。烟灰之上，一场不肯熄灭的复仇在他心中展开。\n\n在那片想象里，他须发尽白，赤面生焰，黑龙载着巨大的魔身破云而起。青龙偃月刀化作夸张的巨刃，随着横扫卷起江潮，将记忆中白衣渡江的军阵连人带舟掀向半空。他想把失守、背叛与无法挽回的败局，一刀劈回发生之前。\n\n可烟云之下，关羽仍被按着双肩，那柄行刑刀也尚未落下。黑龙、魔身与翻卷的白衣，都是这一瞬间的心中幻象。画面以麦城与白衣渡江为背景作幻想改编，现实并未被复仇的想象改写。", "move": "魔关羽握住残旗，前伸魔掌牵引赤红魂焰，黑龙随掌势向前扑出。白发、赤瞳与怒涛般的焰流延续最终魔卡的复仇形象；本篇传记的改写不另设新的主动技能名称。", "storyTitle": "麦城未醒"}, {"id": "mecha6", "tier": 6, "name": "封侯机甲关羽", "assets": {"avatar": {"src": "assets/mecha6-avatar.webp", "width": 1254, "height": 1254, "label": "六星机甲关羽-头像-透明"}, "card": {"src": "assets/mecha6-card.webp", "width": 1024, "height": 1536, "label": "六星机甲关羽-五星版式-侯印召天光"}, "biography": {"src": "assets/mecha6-biography.webp", "width": 1536, "height": 1024, "label": "六星机甲关羽-传记-擎天护城"}, "attack_cg": {"src": "assets/mecha6-attack_cg.webp", "width": 1536, "height": 1024, "label": "六星机甲关羽-放招-擎天巨盾-透明"}}, "story": "黑云压过群山，城中的人们抬头望去，只见苍穹越来越暗。关羽在胸舱中稳住操纵柄，驱动青金巨甲立于城上，双臂向天举起。\n\n环形护阵与龙首翼片一同展开，青色光幕从掌心铺向四方，连成覆盖城郭的穹顶。沉重的黑暗留在天幕之外，暖光落回城墙、屋瓦与人群之间。孩子松开了紧攥的衣角，街上的人也终于停下奔逃，仰望撑住天幕的身影。\n\n巨甲没有退让。关羽守着这座城，也守着每一个还要平安归家的人。楼阁间亮起的灯火，便是他继续举起双臂的理由。", "move": "巨甲屈膝沉身，将近身高的宽厚青金巨盾向前撑出，另一手长刀斜护侧翼。完整盾面、龙纹与收束的能量线构成画面重心，背轮、龙翼及胸舱驾驶者保持可辨。只表现守御蓄势，不加入敌方光束或弹道。", "storyTitle": "擎天护城"}, {"id": "heritage6", "tier": 6, "name": "传承关羽 · 龙魂真身", "assets": {"card": {"src": "assets/heritage6-card.webp", "width": 1024, "height": 1536, "label": "传承关羽-六星封侯-龙魂真身-重制候选"}}}, {"id": "divine6", "tier": 6, "name": "神关羽 · 六臂帝君", "assets": {"card": {"src": "assets/divine6-card.webp", "width": 1024, "height": 1536, "label": "神关羽-六星封侯-六臂帝君-重制候选"}}}, {"id": "demon6", "tier": 6, "name": "魔关羽 · 冥龙魔君", "assets": {"card": {"src": "assets/demon6-card.webp", "width": 1024, "height": 1536, "label": "魔关羽-六星封侯-冥龙魔君-重制候选"}}}];